#!/usr/bin/env node
// The iPhone safe-area and touch rules of the design-check item (design-system#137).
// Unlike scripts/design-detect.sh this check blocks: it exits 1 when a UI file the
// change touched breaks a rule. It scans only files changed since <base-sha>, so an
// untouched file with an old finding never fails a PR.
//
//   node scripts/design-rules.mjs <base-sha>
//
// Exit status: 0 clean, 1 findings, 2 usage error.
//
// Rules (each one explains itself in its message):
//   viewport-height-unit      min-h-screen, h-screen, 100vh
//   viewport-fit-cover        a viewport meta with no viewport-fit=cover
//   fixed-without-safe-edge   fixed positioning with no max(…env…) edge
//   side-inset-without-floor  env(safe-area-inset-left|right) with no non-zero floor
//   form-text-under-16        a form control under 16px at any breakpoint
//   focus-ring-alpha-only     a focus indicator that is only a translucent ring
//
// The checks are textual. They read class strings and CSS declarations, not the
// rendered page, so they catch the common slips, not every possible one. A line that
// is right for a reason the rule cannot see takes a `design-rules-ignore` comment on
// that line or the line above.
//
// Shipped by the frontend `design-check` registry item. The registry-owned ui
// directory (components.json `aliases.ui`) is never scanned: `shadcn add` put those
// files there, so a finding there is the registry's, not this app's.
import { execFileSync } from "node:child_process"
import { readFileSync } from "node:fs"
import { fileURLToPath } from "node:url"

const IGNORE_MARKER = "design-rules-ignore"
const UI_FILE = /\.(?:tsx|jsx|css|html|vue|svelte)$/

const lineOf = (text, index) => text.slice(0, index).split("\n").length

const lineIsIgnored = (lines, line) =>
  (lines[line - 1] ?? "").includes(IGNORE_MARKER) || (lines[line - 2] ?? "").includes(IGNORE_MARKER)

// A class token without its variant prefixes: `md:hover:fixed` -> `fixed`.
const stripVariants = (token) => {
  let rest = token
  for (;;) {
    const next = rest.replace(/^(?:[a-z0-9_-]+(?:\/[a-z0-9_-]+)?|\[[^\]\s]*\]):/i, "")
    if (next === rest) break
    rest = next
  }
  return rest.replace(/^!/, "")
}

// Every quoted run on one line (backtick runs may span lines): the strings a class
// list lives in. Each quote kind is read on its own so an apostrophe in prose cannot
// pair with a double quote elsewhere.
const quotedStrings = (text) => {
  const found = []
  for (const pattern of [/"([^"\n]*)"/g, /'([^'\n]*)'/g, /`([^`]*)`/g]) {
    for (const match of text.matchAll(pattern)) found.push({ value: match[1], index: match.index + 1 })
  }
  return found
}

const classTokens = (value) => value.split(/\s+/).filter(Boolean)

// A string that reads as a class list: more than one token, one of them utility-shaped.
const looksLikeClassList = (tokens) => tokens.length > 1 && tokens.some((token) => /[-:[]/.test(token))

// The text of the CSS block (or style object) around `index`.
const enclosingBlock = (text, index) => {
  const start = Math.max(text.lastIndexOf("{", index), 0)
  const end = text.indexOf("}", index)
  return text.slice(start, end === -1 ? text.length : end + 1)
}

const findings = (file, text, rule, message, matches) => {
  const lines = text.split("\n")
  return matches
    .map((index) => ({ file, rule, message, line: lineOf(text, index) }))
    .filter((finding) => !lineIsIgnored(lines, finding.line))
    .map((finding) => ({ ...finding, snippet: (lines[finding.line - 1] ?? "").trim().slice(0, 140) }))
}

const viewportHeightUnit = (file, text) => {
  const matches = []
  for (const { value, index } of quotedStrings(text)) {
    for (const match of value.matchAll(/(?<![\w-])(?:[\w[\]:!/.-]+:)?(?:min-)?h-screen(?![\w-])/g)) {
      matches.push(index + match.index)
    }
  }
  // The min-h-app utility ships its own 100vh fallback inside this block; it is the
  // one place the unit is right.
  const unguarded = text.replace(/@supports not \([^)]*dvh[^)]*\)\s*\{[^{}]*\}/g, (block) => " ".repeat(block.length))
  for (const match of unguarded.matchAll(/(?<![\w.])100vh(?![\w])/g)) matches.push(match.index)
  return findings(
    file,
    text,
    "viewport-height-unit",
    "min-h-screen, h-screen and 100vh are taller than the visible area on iOS Safari. Use min-h-app (or h-dvh).",
    [...new Set(matches)],
  )
}

const viewportFitCover = (file, text) => {
  const matches = [...text.matchAll(/<meta\b[^>]*\bname=["']viewport["'][^>]*>/gi)]
    .filter((match) => !/viewport-fit\s*=\s*cover/i.test(match[0]))
    .map((match) => match.index)
  return findings(
    file,
    text,
    "viewport-fit-cover",
    "The viewport meta needs viewport-fit=cover, or env(safe-area-inset-*) is always 0. Use the app-html-head item.",
    matches,
  )
}

const SAFE_EDGE_HINT = /env\(|max\(|-edge\b|-edge-|inset-corner|-safe\b|--edge-|--safe-/

const fixedWithoutSafeEdge = (file, text) => {
  const matches = []
  for (const { value, index } of quotedStrings(text)) {
    const tokens = classTokens(value)
    if (!looksLikeClassList(tokens)) continue
    const bases = tokens.map(stripVariants)
    if (!bases.includes("fixed")) continue
    if (bases.includes("inset-0") || bases.some((token) => SAFE_EDGE_HINT.test(token))) continue
    matches.push(index + value.search(/(?<![\w-])(?:[\w[\]:!/.-]+:)?fixed(?![\w-])/))
  }
  for (const match of text.matchAll(/position\s*:\s*["']?fixed\b/g)) {
    const block = enclosingBlock(text, match.index)
    if (/\binset\s*:\s*0\b/.test(block) || SAFE_EDGE_HINT.test(block)) continue
    matches.push(match.index)
  }
  return findings(
    file,
    text,
    "fixed-without-safe-edge",
    "A fixed element needs a max(…env(safe-area-inset-*)…) edge: use inset-corner-br, px-edge, pb-edge or the --edge-* tokens.",
    matches,
  )
}

// The arguments of every max( call that encloses `index`, innermost first.
const enclosingMaxArguments = (text, index) => {
  const calls = []
  let depth = 0
  for (let at = index - 1; at >= 0; at -= 1) {
    const char = text[at]
    if (char === ")") depth += 1
    else if (char === "(") {
      if (depth > 0) {
        depth -= 1
        continue
      }
      if (/max$/.test(text.slice(0, at))) {
        let closing = 0
        let end = at
        for (; end < text.length; end += 1) {
          if (text[end] === "(") closing += 1
          else if (text[end] === ")" && (closing -= 1) === 0) break
        }
        calls.push(splitTopLevel(text.slice(at + 1, end)))
      }
    } else if (/[;{}"'`\n]/.test(char)) break
  }
  return calls
}

const splitTopLevel = (text) => {
  const parts = []
  let depth = 0
  let current = ""
  for (const char of text) {
    if (char === "(") depth += 1
    if (char === ")") depth -= 1
    if (char === "," && depth === 0) {
      parts.push(current)
      current = ""
    } else current += char
  }
  parts.push(current)
  return parts.map((part) => part.trim())
}

const isZero = (value) => /^0(?:\.0+)?(?:px|rem|em|%)?$/.test(value)

const sideInsetWithoutFloor = (file, text) => {
  const matches = []
  for (const match of text.matchAll(/env\(\s*safe-area-inset-(?:left|right)\b/g)) {
    const declarationStart = Math.max(
      text.lastIndexOf(";", match.index),
      text.lastIndexOf("{", match.index),
      text.lastIndexOf("}", match.index),
    )
    // --safe-l: env(safe-area-inset-left, 0px) defines a token; it is not a use.
    if (/^\s*--[\w-]+\s*:/.test(text.slice(declarationStart + 1, match.index))) continue
    // The theme's own pl-safe and pr-safe definitions land in the consumer's css; their
    // uses are what the rule flags, below.
    if (/@utility\s+p[lr]-safe\s*$/.test(text.slice(0, text.lastIndexOf("{", match.index)).trimEnd())) continue
    const hasFloor = enclosingMaxArguments(text, match.index).some((args) =>
      args.some((arg) => !arg.includes("env(") && !isZero(arg)),
    )
    if (!hasFloor) matches.push(match.index)
  }
  for (const { value, index } of quotedStrings(text)) {
    for (const match of value.matchAll(/(?<![\w-])(?:[\w[\]:!/.-]+:)?p[xlr]-safe(?![\w-])/g)) {
      if (!/^(?:[\w[\]:!/.-]+:)?(?:px|pl|pr)-safe$/.test(match[0])) continue
      matches.push(index + match.index)
    }
  }
  return findings(
    file,
    text,
    "side-inset-without-floor",
    "env(safe-area-inset-left|right) is 0 in Safari and in landscape, so a bare inset puts content on the curve. Use px-edge, --edge-x or max(<min>, env(…)).",
    [...new Set(matches)],
  )
}

const FORM_TAG = /<(?:input|textarea|select|Input|Textarea|Select|SelectTrigger|CommandInput|InputGroupInput|InputGroupTextarea)\b/g

const smallTextToken = (token) => {
  const base = stripVariants(token)
  if (/^text-(?:xs|sm|2xs|3xs)$/.test(base)) return true
  const arbitrary = /^text-\[(\d+(?:\.\d+)?)(px|rem)\]$/.exec(base)
  if (!arbitrary) return false
  return Number(arbitrary[1]) * (arbitrary[2] === "rem" ? 16 : 1) < 16
}

const tagEnd = (text, start) => {
  const selfClosing = text.indexOf("/>", start)
  const closing = text.indexOf("</", start)
  const candidates = [selfClosing, closing].filter((at) => at !== -1)
  return Math.min(...candidates, text.length, start + 800)
}

const formTextUnder16 = (file, text) => {
  const matches = []
  for (const tag of text.matchAll(FORM_TAG)) {
    const region = text.slice(tag.index, tagEnd(text, tag.index))
    for (const { value } of quotedStrings(region)) {
      const small = classTokens(value).find(smallTextToken)
      if (small) {
        matches.push(tag.index + region.indexOf(small))
        break
      }
    }
  }
  return findings(
    file,
    text,
    "form-text-under-16",
    "iOS zooms the page when a focused field is under 16px. Keep form text at text-base or larger at every breakpoint (no md:text-sm).",
    matches,
  )
}

const ALPHA_RING = /^focus(?:-visible|-within)?:ring-[a-z-]+\/\d+$/
const SOLID_FOCUS =
  /^focus(?:-visible)?:(?:outline-(?!none$|hidden$)\S+|border-(?!transparent$)\S+|ring-(?:ring|primary|foreground|destructive))$/

const focusRingAlphaOnly = (file, text) => {
  const matches = []
  for (const { value, index } of quotedStrings(text)) {
    const tokens = classTokens(value)
    const ringed = tokens.find((token) => ALPHA_RING.test(token))
    if (!ringed) continue
    const solid = tokens.some((token) => !token.includes("/") && SOLID_FOCUS.test(token))
    if (!solid) matches.push(index + value.indexOf(ringed))
  }
  return findings(
    file,
    text,
    "focus-ring-alpha-only",
    "A translucent focus ring (ring-ring/50) is below 3:1 on the page. Add a solid outline or border-ring beside it (WCAG 1.4.11).",
    matches,
  )
}

const RULES = [viewportHeightUnit, viewportFitCover, fixedWithoutSafeEdge, sideInsetWithoutFloor, formTextUnder16, focusRingAlphaOnly]

export function checkSource(file, text) {
  return RULES.flatMap((rule) => rule(file, text)).sort((a, b) => a.line - b.line || a.rule.localeCompare(b.rule))
}

const git = (...args) => execFileSync("git", args, { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 })

// The ui directory each components.json names, as a path prefix with a trailing slash.
function registryOwnedDirs(topLevel) {
  const dirs = []
  const configs = git("-C", topLevel, "ls-files", "--", ":(glob)**/components.json").split("\n").filter(Boolean)
  for (const config of configs) {
    try {
      const aliases = JSON.parse(readFileSync(`${topLevel}/${config}`, "utf8")).aliases ?? {}
      const alias = aliases.ui ?? (aliases.components ? `${aliases.components}/ui` : null)
      // A workspace-package alias (@scope/pkg/dir) cannot be mapped to a directory.
      if (!alias || (alias.startsWith("@") && !alias.startsWith("@/"))) continue
      dirs.push(`${alias.replace(/^(?:@|~|#)\//, "").replace(/^\.\//, "").replace(/\/$/, "")}/`)
    } catch (error) {
      console.error(`design-rules: could not read ${config}: ${error.message}`)
    }
  }
  return dirs
}

export function main(argv) {
  if (argv.length !== 1) {
    console.error("usage: design-rules.mjs <base-sha>")
    return 2
  }
  const topLevel = git("rev-parse", "--show-toplevel").trim()
  const owned = registryOwnedDirs(topLevel)
  const changed = git("-C", topLevel, "diff", "--name-only", "--diff-filter=d", argv[0], "HEAD")
    .split("\n")
    .filter((path) => UI_FILE.test(path))
    .filter((path) => !owned.some((dir) => path.startsWith(dir) || path.includes(`/${dir}`)))

  const all = changed.flatMap((path) => checkSource(path, readFileSync(`${topLevel}/${path}`, "utf8")))
  const heading = `### Design rules (${changed.length} changed UI file(s) scanned)`
  const lines = [heading, "", all.length === 0 ? "No findings." : `${all.length} finding(s):`, ""]
  for (const finding of all) lines.push(`- \`${finding.file}:${finding.line}\` ${finding.rule}: ${finding.message}`)
  console.log(lines.join("\n"))
  return all.length === 0 ? 0 : 1
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) process.exit(main(process.argv.slice(2)))

#!/usr/bin/env node
// Reports registry files in a consumer that match an older release than the consumer's pin.
// Moving the `@frontend` pin in components.json does not move the code `shadcn add` already
// copied into the app, so a fix the pin has had for months can still be missing from a copy
// (frontend#211). This check lists those copies. It does not change a file.
//
//   node scripts/registry-stale.mjs [--pin <tag>] [--registry-url <template>] [--remote <git url>]
//
// For every components.json in the repo it reads the pin from `registries["@frontend"]`
// (or the old `@design-system`), finds the copies under `aliases.ui` and `aliases.components`
// that carry a registry file's name, and fingerprints each against the registry at the pin.
// A copy that differs from the pin is then compared with every older release. One that equals
// one of them is stale. One that equals none is a local edit or a fork, and is not reported.
//
// Warn-only: the workflow step is continue-on-error, so it never blocks a merge.
// Exit status: 0 nothing stale, 1 the registry could not be read, 2 stale copies found.
//
// Needs `git` and Node 20 or later (global fetch). It reads release tags with
// `git ls-remote` and each item's `r/<item>.json` over HTTP from the URL the pin names.
//
// Shipped by the frontend `design-check` registry item. The audit in
// docs/audits/primitives-usage uses the same fingerprint (`fingerprint` below).
import { execFileSync } from "node:child_process"
import { appendFileSync, readFileSync } from "node:fs"
import { basename, dirname } from "node:path"
import { fileURLToPath } from "node:url"

const SEMVER = /^v(\d+)\.(\d+)\.(\d+)$/
const PINNED_URL = /^(.*)\/(v\d+\.\d+\.\d+)\/r\/\{name\}\.json$/
const RAW_BASE = /^https:\/\/raw\.githubusercontent\.com\/([^/]+)\/([^/]+)$/
const TEMPLATE_TAIL = /\/[^/]+\/r\/\{name\}\.json$/
const ALIASES = ["@frontend", "@design-system"]
const FETCH_CONCURRENCY = 8
const FETCH_TIMEOUT_MS = 20_000

// What the shadcn CLI changes on install, undone so a consumer copy can be compared with
// the registry source: the "use client" directive (dropped when rsc is false), a leading
// comment block, and the cn-* marker classes and font-heading (removed by the style
// transform, which also reflows the cn() call they sat in).
// The comment is only stripped from the registry side: a comment a consumer added is an edit.
export function normaliseSource(source, { stripLeadingComment = false } = {}) {
  const body = source.replaceAll("\r\n", "\n").replace(/^\s*["']use client["'];?\s*\n+/, "")
  const uncommented = stripLeadingComment ? body.replace(/^(?:\s*\/\/[^\n]*\n)+/, "").replace(/^\s*\/\*[\s\S]*?\*\/\s*\n/, "") : body
  return uncommented
    .replace(/\s?\b(?:cn-[a-z-]+|font-heading)\b/g, "")
    .split("\n")
    .map((line) => line.trimEnd())
    .join("\n")
    .trim()
}

// Two copies with the same fingerprint differ only in whitespace and the transforms above.
export function fingerprint(source, options) {
  return normaliseSource(source, options).replace(/\s+/g, "")
}

const versionOf = (tag) => SEMVER.exec(tag).slice(1).map(Number)
const compareTags = (a, b) => {
  const [x, y] = [versionOf(a), versionOf(b)]
  return x[0] - y[0] || x[1] - y[1] || x[2] - y[2]
}

// The pin a components.json names, or null: { tag, template, remote }. `template` is the
// alias URL with its `{name}` slot, `remote` the git URL of the repository it points at
// (null when the URL is not a raw.githubusercontent.com one).
// A URL not ending in a release tag, such as `main`, is no pin.
export function parsePin(config) {
  for (const alias of ALIASES) {
    const entry = config?.registries?.[alias]
    const template = typeof entry === "string" ? entry : entry?.url
    if (typeof template !== "string") continue
    const match = PINNED_URL.exec(template)
    if (!match) continue
    const raw = RAW_BASE.exec(match[1])
    return { tag: match[2], template, remote: raw ? `https://github.com/${raw[1]}/${raw[2]}.git` : null }
  }
  return null
}

const aliasDir = (alias) =>
  // A workspace-package alias (@scope/pkg/dir) cannot be mapped to a directory.
  !alias || (alias.startsWith("@") && !alias.startsWith("@/"))
    ? null
    : alias.replace(/^(?:@|~|#)\//, "").replace(/^\.\//, "").replace(/\/$/, "")

// The files, among the repo's tracked paths, that sit directly in the ui directory or the
// components directory of the app a components.json describes.
export function uiFilesOf(configPath, config, listed) {
  const appDir = dirname(configPath) === "." ? "" : `${dirname(configPath)}/`
  const aliases = config?.aliases ?? {}
  const uiAlias = aliases.ui ?? (aliases.components ? `${aliases.components}/ui` : null)
  const dirs = [aliasDir(uiAlias), aliasDir(aliases.components)].filter(Boolean)
  const wanted = new Set()
  for (const dir of dirs) {
    for (const prefix of ["", "src/"]) wanted.add(`${appDir}${prefix}${dir}/`)
  }
  return listed
    .filter((path) => /\.(?:tsx|ts)$/.test(path))
    .filter((path) => {
      const folder = path.slice(0, path.lastIndexOf("/") + 1)
      return wanted.has(folder)
    })
    .sort()
}

// Runs `task` over `items`, at most `limit` at a time, and keeps the order of the results.
async function mapLimit(items, limit, task) {
  const results = new Array(items.length)
  let next = 0
  const worker = async () => {
    while (next < items.length) {
      const index = next++
      results[index] = await task(items[index])
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker))
  return results
}

// Fingerprints each copy against the registry at `pin`, then against every older release.
//   files:     [{ path, text }]
//   tags:      every release tag; only those older than the pin are read
//   loadIndex: (tag) => Promise<{ items: [{ name, files: [{ path }] }] }>   (r/registry.json)
//   loadItem:  (tag, name) => Promise<{ files: [{ path, content }] } | null> (r/<name>.json; null: no such item)
export async function findStale({ files, pin, tags, loadIndex, loadItem }) {
  const index = await loadIndex(pin)
  const itemOf = new Map()
  for (const entry of index.items) {
    for (const file of entry.files ?? []) if (!itemOf.has(basename(file.path))) itemOf.set(basename(file.path), entry.name)
  }
  const older = tags.filter((tag) => compareTags(tag, pin) < 0).sort(compareTags)

  const cache = new Map()
  const failed = new Set()
  const item = (tag, name) => {
    const key = `${tag}/${name}`
    if (!cache.has(key)) {
      cache.set(
        key,
        loadItem(tag, name).catch(() => {
          failed.add(key)
          return null
        }),
      )
    }
    return cache.get(key)
  }
  const contentAt = async (tag, name, file) => {
    const found = (await item(tag, name))?.files.find((candidate) => basename(candidate.path) === file)
    return found?.content ?? null
  }
  const matches = (copy, content) =>
    content !== null && [fingerprint(content), fingerprint(content, { stripLeadingComment: true })].includes(copy)

  const result = { checked: 0, identical: [], stale: [], unreadable: 0 }
  for (const file of files) {
    const name = itemOf.get(basename(file.path))
    if (!name) continue
    const atPin = await contentAt(pin, name, basename(file.path))
    if (atPin === null) continue
    result.checked += 1
    const copy = fingerprint(file.text)
    if (matches(copy, atPin)) {
      result.identical.push(file.path)
      continue
    }
    const hits = (
      await mapLimit(older, FETCH_CONCURRENCY, async (tag) => (matches(copy, await contentAt(tag, name, basename(file.path))) ? tag : null))
    ).filter(Boolean)
    if (hits.length > 0) result.stale.push({ path: file.path, first: hits[0], last: hits.at(-1), pin })
  }
  result.unreadable = failed.size
  return result
}

const release = ({ first, last }) => (first === last ? first : `${first} to ${last}`)

export function formatReport({ app, pin, checked, identical, stale, unreadable }) {
  const lines = [`### Registry copies older than the pin (\`${app}\`, pin ${pin}, not blocking)`, ""]
  if (stale.length === 0) {
    lines.push(`No copy is older than ${pin}: ${identical.length} of ${checked} registry copies match it.`, "")
  } else {
    lines.push(
      `${stale.length} of ${checked} registry copies match an older release than ${pin}:`,
      "",
      "| File | Matches | Pin |",
      "|---|---|---|",
      ...stale.map((entry) => `| \`${entry.path}\` | ${release(entry)} | ${entry.pin} |`),
      "",
      "Look at the diff, then bring a copy to the pin with `npx shadcn add @frontend/<item> --overwrite`. It replaces local edits.",
      "",
    )
  }
  if (unreadable > 0) lines.push(`Incomplete: ${unreadable} release file(s) could not be read, so a copy may match a release not listed.`, "")
  return lines.join("\n")
}

const git = (...args) => execFileSync("git", args, { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 })

async function fetchJson(url, { missingIsNull }) {
  const response = await fetch(url, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) })
  if (response.status === 404 && missingIsNull) return null
  if (!response.ok) throw new Error(`${url} answered ${response.status}`)
  return response.json()
}

const urlAt = (template, tag, name) => template.replace(TEMPLATE_TAIL, `/${tag}/r/{name}.json`).replace("{name}", name)

function releaseTags(remote) {
  return git("ls-remote", "--tags", "--refs", remote)
    .split("\n")
    .map((line) => line.split("\t")[1]?.replace(/^refs\/tags\//, ""))
    .filter((tag) => tag && SEMVER.test(tag))
    .sort(compareTags)
}

function parseArgs(argv) {
  const options = {}
  const known = { "--pin": "pin", "--registry-url": "registryUrl", "--remote": "remote" }
  for (let index = 0; index < argv.length; index += 2) {
    const key = known[argv[index]]
    if (!key || argv[index + 1] === undefined) return null
    options[key] = argv[index + 1]
  }
  return options
}

export async function main(argv) {
  const options = parseArgs(argv)
  if (!options) {
    console.error("usage: registry-stale.mjs [--pin <tag>] [--registry-url <template>] [--remote <git url>]")
    return 2
  }
  const topLevel = git("rev-parse", "--show-toplevel").trim()
  const listed = git("-C", topLevel, "ls-files").split("\n").filter(Boolean)
  const configs = listed.filter((path) => basename(path) === "components.json")

  const out = []
  const emit = () => {
    const text = out.join("\n")
    console.log(text)
    if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${text}\n`)
  }
  let status = 0
  const releaseCache = new Map()

  for (const configPath of configs) {
    const app = dirname(configPath)
    try {
      const config = JSON.parse(readFileSync(`${topLevel}/${configPath}`, "utf8"))
      const parsed = parsePin(config)
      const tag = options.pin ?? parsed?.tag
      const template = options.registryUrl ?? parsed?.template
      if (!tag || !template) {
        out.push(`### Registry copies older than the pin (\`${app}\`, not blocking)`, "", `\`${configPath}\` has no pin: add a \`registries["@frontend"]\` URL ending \`/<tag>/r/{name}.json\`, or pass \`--pin\` and \`--registry-url\`.`, "")
        continue
      }
      const remote = options.remote ?? parsed?.remote
      if (!remote) throw new Error("could not list releases: pass --remote with the repository's git URL")
      if (!releaseCache.has(remote)) releaseCache.set(remote, releaseTags(remote))

      const files = uiFilesOf(configPath, config, listed).map((path) => ({ path, text: readFileSync(`${topLevel}/${path}`, "utf8") }))
      const result = await findStale({
        files,
        pin: tag,
        tags: releaseCache.get(remote),
        loadIndex: async (at) => {
          try {
            return await fetchJson(urlAt(template, at, "registry"), { missingIsNull: false })
          } catch (error) {
            throw new Error(`could not read the registry at ${at}: ${error.message}`)
          }
        },
        loadItem: (at, name) => fetchJson(urlAt(template, at, name), { missingIsNull: true }),
      })
      out.push(formatReport({ app, pin: tag, ...result }))
      if (result.stale.length > 0 && status === 0) status = 2
    } catch (error) {
      out.push(`### Registry copies older than the pin (\`${app}\`, not blocking)`, "", `${configPath}: ${error.message}`, "")
      status = 1
    }
  }
  if (configs.length === 0) out.push("### Registry copies older than the pin", "", "No components.json found.", "")
  emit()
  return status
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (error) => {
      console.error(error)
      process.exit(1)
    },
  )
}
